document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("contact-form"),t=document.getElementById("sendmessage"),n=document.getElementById("errormessage");e&&e.addEventListener("submit",async function(s){s.preventDefault(),t.classList.add("d-none"),n.classList.add("d-none");const a={name:document.getElementById("name").value.trim(),email:document.getElementById("email").value.trim(),subject:document.getElementById("subject").value.trim(),message:document.getElementById("message").value.trim()};if(a.name.length<2||a.name.length>100)return n.textContent="Name must be between 2-100 characters.",void n.classList.remove("d-none");if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a.email))return n.textContent="Please enter a valid email address.",void n.classList.remove("d-none");if(a.subject.length<2||a.subject.length>200)return n.textContent="Subject must be between 2-200 characters.",void n.classList.remove("d-none");if(a.message.length<10||a.message.length>5e3)return n.textContent="Message must be between 10-5000 characters.",void n.classList.remove("d-none");const o=e.querySelector('button[type="submit"]'),r=o.textContent;o.disabled=!0,o.innerHTML='<i class="fa fa-spinner fa-spin"></i> Sending...';try{const n=await fetch("https://comment-handler.baha-erdogann.workers.dev/contact",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(a)}),s=await n.json();if(!n.ok)throw new Error(s.error||`HTTP ${n.status}`);t.textContent=s.message||"Your message has been sent successfully!",t.classList.remove("d-none"),e.reset(),t.scrollIntoView({behavior:"smooth",block:"nearest"})}catch(e){console.error("Contact form error:",e);let t="Failed to send message. Please try again later.";(e.message.includes("Rate limit")||e.message.includes("characters"))&&(t=e.message),n.textContent=t,n.classList.remove("d-none")}finally{o.disabled=!1,o.textContent=r}})});